  ('a6592204-2a49-5fe4-9acb-eaf50371d5bf', null, (select id from public.skills where slug = 'read-g12-authors-purpose'), null, 'hard',
   $q$What is the function of the sentences "None of these people stopped the change. That is not my point."?$q$, $q$[{"text":"They express the author's disappointment that the councils and residents of the valley did not resist the railway more firmly.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"They signal a shift away from the towns toward the railway company, whose decision the author will now examine in detail.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"They head off a likely misreading, that the author credits resistance with winning, and narrow the claim to how the change happened.","is_correct":true},{"text":"They concede that the author's examples are irrelevant, since the townspeople had no real effect on the outcome of the change.","is_correct":false,"misconception_token":"reverses-viewpoint"}]$q$::jsonb, $q$They head off a likely misreading, that the author credits resistance with winning, and narrow the claim to how the change happened.$q$, $q$After describing Ashby's refusal, readers might think the author is telling a story of successful resistance; the author rules that out and restates the actual claim that the change "was argued over, tested, and gradually accepted." This makes the argument harder to dismiss, not an admission that the examples do not matter.$q$, 'draft', 'a10f0fdd-fb91-54a2-8706-60ff47a4f21d')
