  ('4644c24d-5b28-525b-bfe1-f6378dcfefef', null, (select id from public.skills where slug = 'read-g12-authors-purpose'), null, 'medium',
   $q$Why does the author list woodpeckers, owls, bats, flying squirrels, beetles, and fungi in the second paragraph?$q$, $q$[{"text":"The list warns that these creatures are damaging the forest and must be controlled by the park staff.","is_correct":false,"misconception_token":"reverses-viewpoint"},{"text":"The list ranks the creatures from most to least important so visitors know which ones to protect first.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"The pile of examples shows how much life a dead tree holds, countering the impression that it is lifeless.","is_correct":true},{"text":"The list identifies the animals visitors are most likely to see from the trail on an average afternoon.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$The pile of examples shows how much life a dead tree holds, countering the impression that it is lifeless.$q$, $q$The accumulation supports the claim that a snag is "one of the busiest places in this forest." The creatures are presented as reasons to keep the trees, not as pests or as a ranked list.$q$, 'draft', 'cc97a657-c4a9-53ca-be12-656d8a1b34e2')
