  ('3b179205-2244-503e-bfde-a7c6af1049d8', null, (select id from public.skills where slug = 'read-g12-authors-purpose'), null, 'medium',
   $q$Why does the speaker describe the bassoon as looking "like a piece of plumbing someone decided to varnish"?$q$, $q$[{"text":"The description warns families that the bassoon is fragile and must be varnished regularly to protect it.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The description explains that bassoons are made from the same metal pipes used in household plumbing.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The description shows that the speaker secretly dislikes the bassoon and would rather teach a different instrument.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"The self-mocking humor acknowledges the instrument's odd look, which disarms resistance before the speaker argues for it.","is_correct":true}]$q$::jsonb, $q$The self-mocking humor acknowledges the instrument's odd look, which disarms resistance before the speaker argues for it.$q$, $q$By joking about the bassoon's appearance first, the speaker admits what families are already thinking and wins goodwill. The rest of the talk praises the instrument, so the joke is affectionate, not a sign of dislike.$q$, 'draft', 'ca2f3581-9821-590e-a114-8dc8d2fb1fb1')
