  ('85a7b19b-8454-5956-a023-c34189c35c8a', null, (select id from public.skills where slug = 'read-g12-authors-purpose'), null, 'medium',
   $q$How does the speaker organize the argument, and what does that order reveal?$q$, $q$[{"text":"The speaker gives an artistic reason first and a practical reason second, signaling that auditions matter most.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"The speaker gives a practical reason first and an artistic reason second, signaling that the artistic reason matters more.","is_correct":true},{"text":"The speaker tells a story about one former student, signaling that personal experience is the only source of evidence.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"The speaker lists every instrument in the orchestra in order, signaling that all of them are equally worth choosing.","is_correct":false,"misconception_token":"misreads-structure"}]$q$::jsonb, $q$The speaker gives a practical reason first and an artistic reason second, signaling that the artistic reason matters more.$q$, $q$The speaker announces "a practical argument, and then a less practical one," and later says the second "is the one I actually care about." Saving it for last gives it the most weight.$q$, 'draft', 'ca2f3581-9821-590e-a114-8dc8d2fb1fb1')
