values
  ('769f94b9-c804-5b50-bd9f-16afbae373cf', null, (select id from public.skills where slug = 'read-g12-figurative-language'), null, 'easy',
   $q$A traveler "faced a forest of conflicting numbers." What does the metaphor "forest" emphasize?$q$, $q$[{"text":"The calm, peaceful feeling of waiting for a train","is_correct":false,"misconception_token":"misreads-tone"},{"text":"That many railroad stations were built in wooded areas","is_correct":false,"misconception_token":"literal-reading"},{"text":"The overwhelming and confusing number of different times","is_correct":true},{"text":"That the timetables were printed on paper made from trees","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$The overwhelming and confusing number of different times$q$, $q$A forest is dense and easy to get lost in, so the metaphor shows how crowded and confusing the competing times were for a traveler. The word is figurative and has nothing to do with where stations stood.$q$, 'draft', '5b4a954b-e234-57ca-8bbc-c282b017bb02')
