  ('c3245635-b958-52ce-9a31-0128594689cb', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'easy',
   $q$What structural choice does the poet make at the beginning and end of the poem?$q$, $q$[{"text":"The poem opens with a question and closes with the scientist's direct answer to it.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The poem opens with the mentor speaking and closes with the student speaking instead.","is_correct":false,"misconception_token":"misidentifies-speaker"},{"text":"The poem opens and closes with nearly the same lines about the stake and the ice.","is_correct":true},{"text":"The poem opens in the present and closes many years in the past with the mentor.","is_correct":false,"misconception_token":"misreads-structure"}]$q$::jsonb, $q$The poem opens and closes with nearly the same lines about the stake and the ice.$q$, $q$The first two lines of the poem return almost word for word in the last stanza, creating a frame. The mentor never speaks directly, and the final stanza looks forward to next year, not back.$q$, 'draft', '3ec31ea2-aa88-543c-afa9-4ea25ff7b8e2')
