  ('fe004062-5386-5937-9650-177536df0f4c', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'easy',
   $q$How is the clock tower's view of itself different from the way the story presents it?$q$, $q$[{"text":"The tower thinks it is useless, but the story shows it is the most important object in town.","is_correct":false,"misconception_token":"reverses-meaning"},{"text":"The tower thinks it is essential, but the story shows the town can manage without it.","is_correct":true},{"text":"The tower thinks the sparrow is helpful, but the story shows the bird causes the broken gear.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The tower thinks the merchants are dishonest, but the story shows they are always fair.","is_correct":false,"misconception_token":"misreads-target"}]$q$::jsonb, $q$The tower thinks it is essential, but the story shows the town can manage without it.$q$, $q$The tower claims "Everyone here depends on me," yet the townspeople switch to the sparrow and do not even notice they need the clock. The storm, not the bird, breaks the gear.$q$, 'draft', '82995920-1dae-53b5-b0f3-13fc0535d6a7')
