values
  ('02abd8ce-3dae-5db7-84b0-1bfd35d96ee7', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'easy',
   $q$The tower "considered this a sign of deep respect" when merchants adjusted their watches. What does this detail in the opening suggest about the tower?$q$, $q$[{"text":"It is modest about its accuracy and wishes the merchants would ignore it.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It is right to feel admired, since the merchants built the tower to honor it.","is_correct":false,"misconception_token":"takes-speaker-literally"},{"text":"It is worried that the merchants will soon stop trusting its bell.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It mistakes ordinary usefulness for admiration, which sets up its pride for a fall.","is_correct":true}]$q$::jsonb, $q$It mistakes ordinary usefulness for admiration, which sets up its pride for a fall.$q$, $q$Merchants setting their watches are simply using a tool, so calling it "deep respect" exposes the tower's vanity early. The opening shows pride, not modesty or worry.$q$, 'draft', '82995920-1dae-53b5-b0f3-13fc0535d6a7')
