  ('1aca7140-693d-5c66-b097-1ed00cc00a8b', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'easy',
   $q$Who is the speaker of this poem?$q$, $q$[{"text":"The girl's father, remembering the year he stopped playing the piano","is_correct":false,"misconception_token":"misidentifies-speaker"},{"text":"A metronome that has kept time in the same practice room for forty years","is_correct":true},{"text":"A piano teacher who has trained both the father and his daughter","is_correct":false,"misconception_token":"misidentifies-speaker"},{"text":"The girl herself, describing her first piano lesson in an empty room","is_correct":false,"misconception_token":"misidentifies-speaker"}]$q$::jsonb, $q$A metronome that has kept time in the same practice room for forty years$q$, $q$The speaker says "I am a pendulum" and "I only click," identifying itself as the metronome. The father and daughter are described in the third person.$q$, 'draft', '17f4d92d-1a54-5d2c-9ec9-97ba34d2b3c2')
