  ('134abfe7-c467-5830-801a-70a18e34ddd0', null, (select id from public.skills where slug = 'read-g12-main-idea-summary'), null, 'medium',
   $q$Which statement would NOT belong in an objective summary of the passage?$q$, $q$[{"text":"Coated roofs stayed cooler and lowered cooling costs, but heating costs and upkeep rose somewhat.","is_correct":false,"misconception_token":"belongs-in-summary"},{"text":"Corvana's planners wisely refused to waste money on a flashy rooftop experiment that only partly worked.","is_correct":true},{"text":"Corvana coated three hundred roofs and compared them with nearby dark roofs over two summers.","is_correct":false,"misconception_token":"belongs-in-summary"},{"text":"The city now pairs grants for coatings with tree planting to keep neighborhoods cooler.","is_correct":false,"misconception_token":"belongs-in-summary"}]$q$::jsonb, $q$Corvana's planners wisely refused to waste money on a flashy rooftop experiment that only partly worked.$q$, $q$An objective summary avoids judgments like "wisely" and "flashy," and this statement also misstates the outcome, since Corvana still offers grants for coatings. The other three choices accurately restate key points.$q$, 'draft', 'ee2e4caa-0d30-50c9-82b9-b7a35382e5a5')
